using System;using System.Collections.Generic;using System.Linq;
namespace Hryushki {
public static class SyncTests {
 static int count;static void Check(bool v,string s){if(!v)throw new Exception(s);count++;}
 static Dictionary<string,object> Product(decimal price){return new Dictionary<string,object>{{"name","Лежанка"},{"HomePrice",price},{"PartnerPrice",650},{"Cost",300},{"sku","LZ-001"}};}
 static Dictionary<string,object> Reply(SyncModel.Request q,int version,bool ok=true){return new Dictionary<string,object>{{"owner","u"},{"ok",ok},{"records",q.All.Values.Select(r=>{var n=J.Copy(r);n["version"]=version;return n;}).ToList()},{"conflicts",new object[0]}};}
 public static int Run(){try{var d=SyncModel.Attach(J.Empty(),"u");d["custom"]=new Dictionary<string,object>{{"value",42}};d["products"]=new[]{Product(680)};SyncModel.Ids(d,false);var q=SyncModel.Prepare(d,"u");Check(q.Changes.Count==1,"new record queued");var acknowledged=SyncModel.Merge(d,q,Reply(q,1),"u");Check(SyncModel.Prepare(acknowledged,"u").Changes.Count==0,"ack clears queue");Check(J.N(SyncModel.Obj(acknowledged,"custom"),"value")==42,"unknown fields retained");
 var fresh=J.Copy(d);J.Rows(fresh,"products")[0]["HomePrice"]=700;var whileEditing=SyncModel.Merge(fresh,q,Reply(q,1),"u");Check(J.N(J.Rows(whileEditing,"products")[0],"HomePrice")==700&&J.N(SyncModel.Prepare(whileEditing,"u").Changes[0],"base_version")==1,"in-flight edits retained with acknowledged base");
 var local=J.Copy(acknowledged);J.Rows(local,"products")[0]["HomePrice"]=710;var localReq=SyncModel.Prepare(local,"u");var remote=J.Copy(acknowledged);J.Rows(remote,"products")[0]["HomePrice"]=720;var conflict=SyncModel.Merge(local,localReq,Reply(SyncModel.Prepare(remote,"u"),2,false),"u");Check(J.Rows(SyncModel.Obj(conflict,"_sync"),"conflicts").Count==1,"conflict retained");var cloud=SyncModel.Resolve(conflict,0,true);Check(J.N(J.Rows(cloud,"products")[0],"HomePrice")==720&&SyncModel.Prepare(cloud,"u").Changes.Count==0,"choose cloud");var ours=SyncModel.Resolve(conflict,0,false);Check(J.N(SyncModel.Prepare(ours,"u").Changes[0],"base_version")==2&&J.N(J.Rows(ours,"products")[0],"HomePrice")==710,"choose local rebases");
 var a=SyncModel.Attach(J.Empty(),"u");a["operations"]=new[]{new Dictionary<string,object>{{"id",1},{"date","03.11.2026"},{"type","Расход"},{"item","Тест"},{"qty",0},{"amount",10}}};SyncModel.Ids(a,false);var b=J.Copy(a);J.Rows(b,"operations")[0]["_syncId"]="other-operation";J.Rows(b,"operations")[0]["amount"]=20;var reply=Reply(SyncModel.Prepare(b,"u"),1);var merged=SyncModel.Merge(a,SyncModel.Prepare(a,"u"),reply,"u");Check(J.Rows(merged,"operations").Count==2&&J.Rows(merged,"operations").Select(o=>J.N(o,"id")).Distinct().Count()==2,"independent numeric IDs do not collide");
 Console.WriteLine("PASS sync checks: "+count);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
}
